export type StructuredOperationId = keyof typeof structuredOperationOutputSchemaFactories

const structuredOperationOutputSchemaCache = new Map<StructuredOperationId, z.ZodTypeAny>()

export function getStructuredOperationOutputSchema<TId extends StructuredOperationId>(id: TId) {
  const cached = structuredOperationOutputSchemaCache.get(id)
  if (cached) return cached

  const schema = structuredOperationOutputSchemaFactories[id]()
  structuredOperationOutputSchemaCache.set(id, schema)
  return schema
}
